    PresentationPorts ports;ports.ready=[this]{return scene_.ready();};ports.archiveReady=[this]{return scene_.canOpen();};ports.enter=[this]{scene_.open();if(model_.archive){SYSTEMTIME now;GetLocalTime(&now);std::ostringstream stamp;stamp<<std::setfill('0')<<std::setw(2)<<now.wHour<<":"<<std::setw(2)<<now.wMinute<<":"<<std::setw(2)<<now.wSecond;auto& albums=model_.library.at("albums");if(!albums.empty()){model_.archiveLog.insert(model_.archiveLog.begin(),{{"id",albums[scene_.selected()].value("id","")},{"time",stamp.str()}});if(model_.archiveLog.size()>256)model_.archiveLog.erase(model_.archiveLog.begin()+256,model_.archiveLog.end());}}};ports.back=[this]{scene_.back();};ports.prepare=[this]{ui_->cancelLocation();};ports.mode=[this](bool detail){model_.detailSurface=detail;};
    ports.select=[this](const Selection& next){scene_.select(next.index,model_.now,false,next.direction,next.horizontal);};ports.switchDetail=[this](const Selection& next){scene_.select(next.index,model_.now,true,next.direction,next.horizontal);};
    ports.showMenu=[this]{detailMotion_.move(true,model_.now,model_.preferences.value("reduced",false));};ports.showBrowse=[this]{browseMotion_.move(true,model_.now,model_.preferences.value("reduced",false));};
    ports.hideMenu=[this](auto done){detailMotion_.move(false,model_.now,model_.preferences.value("reduced",false),std::move(done));};ports.hideBrowse=[this](auto done){browseMotion_.move(false,model_.now,model_.preferences.value("reduced",false),std::move(done));};presentation_=std::make_unique<Presentation>(std::move(ports));
